    int depositCount = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                depositCount++;
                markDeposit(grid, i, j);
            }
        }
    }

    return depositCount;
}

private static void markDeposit(char[][] grid, int row, int col) {
    int[] rowDirections = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] colDirections = {-1, 0, 1, -1, 1, -1, 0, 1};

    grid[row][col] = '*'; // Mark the current cell as visited

    for (int dir = 0; dir < 8; dir++) {
        int newRow = row + rowDirections[dir];
        int newCol = col + colDirections[dir];

        if (isValid(grid, newRow, newCol) && grid[newRow][newCol] == '@') {
            markDeposit(grid, newRow, newCol);
        }
    }
}

private static boolean isValid(char[][] grid, int row, int col) {
    return row >= 0 && row < grid.length && col >= 0 && col < grid[row].length;
}

public static int maxRegions(int N) {
    if (N == 0) return 1; // Base case: No triangles, one region (the whole plane)
    // For N triangles, the formula to calculate the maximum number of regions is:
    // R(N) = 2 + N * (N + 1)
    return 2 + N * (N + 1);
}

public static int maxRegions(int N) {
    if (N == 0) return 1; // Base case: no triangles, one region (the whole plane)
    // The formula to calculate the maximum number of regions
    return 2 + N * (N + 1) / 2;
}

public static int maxRegions(int N) {
    // Base case for 0 triangles
    if (N == 0) return 1;

    // Initialize the maximum regions with the first triangle
    int maxRegions = 2;

    // The number of regions increases based on the formula for N triangles
    for (int i = 1; i <= N; i++) {
        maxRegions += i * 3;
    }

    return maxRegions;
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    int regions = 2; // Starting with 1 triangle which divides the plane into 2 regions
    for (int i = 2; i <= N; i++) {
        regions += 3 * (i - 1);
    }
    return regions;
}

public static int maxRegions(int N) {
    if (N == 0) return 1; // No triangles, one region (the whole plane)
    if (N == 1) return 2; // One triangle divides the plane into 2 regions

    // Formula to calculate the maximum number of regions
    // R(N) = R(N-1) + 3*(N-1) + 1
    // Simplified: R(N) = 2 + 3*(1 + 2 + ... + (N-1)) = 2 + 3*(N-1)*N/2
    return 2 + 3 * (N - 1) * N / 2;
}

