public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    Set<String> pathSet = new HashSet<>();
    for (int[] path : paths) {
        String key = path[0] + "," + path[1];
        pathSet.add(key);
    }
    return canTravel(n, start[0], start[1], end[0], end[1], visited, pathSet) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int i, int j, int endI, int endJ, boolean[][] visited, Set<String> paths) {
    if (i == endI && j == endJ) {
        return true;
    }
    if (i < 0 || i >= n || j < 0 || j >= n || visited[i][j]) {
        return false;
    }
    visited[i][j] = true;

    if (paths.contains(i + "," + (j + 1)) && canTravel(n, i, j + 1, endI, endJ, visited, paths)) {
        return true;
    }
    if (paths.contains(i + "," + (j - 1)) && canTravel(n, i, j - 1, endI, endJ, visited, paths)) {
        return true;
    }
    if (paths.contains((i + 1) + "," + j) && canTravel(n, i + 1, j, endI, endJ, visited, paths)) {
        return true;
    }
    if (paths.contains((i - 1) + "," + j) && canTravel(n, i - 1, j, endI, endJ, visited, paths)) {
        return true;
    }

    visited[i][j] = false; // backtrack
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravel(n, start[0], start[1], end, paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int x, int y, int[] end, int[][] paths, boolean[][] visited) {
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }
    if (x == end[0] && y == end[1]) {
        return true;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        int newX = x + path[0];
        int newY = y + path[1];
        if (canTravel(n, newX, newY, end, paths, visited)) {
            return true;
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(start[0], start[1], end[0], end[1], visited, paths);
    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int ex, int ey, boolean[][] visited, int[][] paths) {
    if (x == ex && y == ey) {
        return true;
    }
    if (x < 0 || x >= visited.length || y < 0 || y >= visited[0].length || visited[x][y]) {
        return false;
    }
    visited[x][y] = true;

    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            if (dfs(path[2], path[3], ex, ey, visited, paths) || 
                dfs(path[3], path[2], ex, ey, visited, paths)) {
                return true;
            }
        }
    }
    return false;
}

