private static boolean dfs(int x, int y, int ex, int ey, boolean[][] visited, int[][] paths, int n) {
    if (x == ex && y == ey) {
        return true;
    }
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        int nx = x + path[0];
        int ny = y + path[1];
        if (dfs(nx, ny, ex, ey, visited, paths, n)) {
            return true;
        }
    }
    visited[x][y] = false;
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravel(n, start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int x, int y, int ex, int ey, int[][] paths, boolean[][] visited) {
    if (x == ex && y == ey) {
        return true;
    }
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        if ((path[0] == x && path[1] == y) || (path[2] == x && path[3] == y)) {
            int nx = path[0] == x && path[1] == y ? path[2] : path[0];
            int ny = path[0] == x && path[1] == y ? path[3] : path[1];
            if (canTravel(n, nx, ny, ex, ey, paths, visited)) {
                return true;
            }
        }
    }
    visited[x][y] = false;
    return false;
}

public static String appx(String word1, String word2) {
    // Convert both words to lowercase to ensure case-insensitivity
    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();

    // Create a set to store unique common letters
    Set<Character> commonLetters = new HashSet<>();

    // Use a set to store characters of the first word
    Set<Character> set1 = new HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    // Check each character in the second word against the first word's set
    for (char c : word2.toCharArray()) {
        if (set1.contains(c)) {
            commonLetters.add(c);
        }
    }

    // Calculate the number of common letters
    int commonCount = commonLetters.size();

    // Calculate the sum of the lengths of the two words
    int totalLength = word1.length() + word2.length();

    // Calculate the greatest common divisor of commonCount and totalLength
    int gcd = gcd(commonCount, totalLength);

    // Reduce the fraction by dividing both numerator and denominator by the gcd
    int numerator = commonCount / gcd;
    int denominator = totalLength / gcd;

    // Return the result as a string in the required format
    if (denominator == 1) {
        return "appx(" + word1.toUpperCase() + ", " + word2.toUpperCase() + ") = " + numerator;
    } else {
        return "appx(" + word1.toUpperCase() + ", " + word2.toUpperCase() + ") = " + numerator + "/" + denominator;
    }
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

