boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // We need to find a subset of k elements with sum s such that s/k = sum/n
    // which is equivalent to ns = sk where s is the sum of subset and k is the size of subset

    // Iterate over possible subset sizes k
    for (int k = 1; k <= n / 2; k++) {
        if (sum * k % n == 0) {
            int targetSum = sum * k / n;
            if (isSubsetWithSum(nums, targetSum, k)) {
                return true;
            }
        }
    }
    return false;
}

private boolean isSubsetWithSum(int[] nums, int targetSum, int k) {
    boolean[][] dp = new boolean[k + 1][targetSum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        // Traverse backwards to avoid using the same element multiple times
        for (int j = k; j >= 1; j--) {
            for (int s = targetSum; s >= num; s--) {
                dp[j][s] = dp[j][s] || dp[j - 1][s - num];
            }
        }
    }

    return dp[k][targetSum];
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];

    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= i / 2; j++) {
            for (int k = 0; k <= sum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (!dp[i][j][k] && j > 0 && k >= nums[i - 1]) {
                    dp[i][j][k] = dp[i - 1][j - 1][k - nums[i - 1]];
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[n][i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
