    int n = nums.length;
    for (int num : nums) {
        totalSum += num;
    }

    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][totalSum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= totalSum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (k >= num) {
                    dp[i][j][k] |= dp[i - 1][j - 1][k - num];
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (totalSum * j % n == 0 && dp[n][j][totalSum * j / n]) {
            return true;
        }
    }

    return false;
}

