        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int s = 0; s <= totalSum - nums[i]; s++) {
                if (dp[j - 1][i][s]) {
                    dp[j][i + 1][s + nums[i]] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (totalSum * i % n == 0 && dp[i][n][totalSum * i / n]) {
