public boolean hasAllCodes(String s, int k) {
    int total = 1 << k; // Total number of binary strings of length k
    boolean[] found = new boolean[total];
    int hashVal = 0;
    int mask = total - 1; // Mask to keep last k bits

    for (int i = 0; i < s.length(); i++) {
        hashVal = ((hashVal << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1 && !found[hashVal]) {
            found[hashVal] = true;
            total--;
            if (total == 0) return true;
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) return false;

    Set<Integer> seen = new HashSet<>();

    int allOnes = (1 << k) - 1;
    int num = 0;

    for (int i = 0; i < s.length(); i++) {
        num = (num << 1) & allOnes | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen.add(num);
        }
    }

    return seen.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<Integer> allSubstrings = new HashSet<>();
    int currentNumber = 0;

    for (int i = 0; i < s.length(); i++) {
        // Append the current bit to the current number
        currentNumber = (currentNumber << 1) & ((1 << k) - 1) | (s.charAt(i) - '0');

        // Only add to set once we have a substring of length k
        if (i >= k - 1) {
            allSubstrings.add(currentNumber);
        }
    }

    return allSubstrings.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) return false;
    Set<String> set = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        String sub = s.substring(i, i + k);
        set.add(sub);
        if (set.size() == 1 << k) return true;
    }
    return false;
}

