public int minInsertions(String s) {
    int open = 0;
    int close = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close % 2 == 1) {
                open++;
                close--;
            }
            close += 2;
        } else {
            close--;
            if (close == -1) {
                open++;
                close = 1;
            }
        }
    }

    return open + close;
}

public int minInsertions(String s) {
    int left = 0; // Number of unmatched '('
    int insertions = 0; // Number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            left++;
        } else {
            if (left > 0) {
                left--; // Match '(' with this ')'
            } else {
                insertions++; // Need to insert '(' to match this ')'
            }
            // If current char is ')', check the next character
            if (c == ')' && (s.length() == 1 || s.charAt(s.indexOf(c) + 1) != ')')) {
                // Need to insert ')' to balance odd number of ')'
                insertions++;
            } else if (c == ')' && s.charAt(s.indexOf(c) + 1) == ')') {
                // Skip the next ')' as it is part of a matched pair
                if (s.indexOf(c) + 1 < s.length()) {
                    c = s.charAt(s.indexOf(c) + 1);
                }
            }
        }
    }

    // Add insertions needed to match remaining '('
    insertions += left * 2;

    return insertions;
}

public int minInsertions(String s) {
    int leftInsertions = 0;
    int rightInsertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            rightInsertions++;
        } else {
            if (rightInsertions > 0) {
                rightInsertions--;
            } else {
                leftInsertions++;
            }
        }
    }

    return leftInsertions + rightInsertions;
}

public int minInsertions(String s) {
    int open = 0, insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            open++;
        } else {
            if (open > 0) {
                open--;
                if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                    i++; // Skip the next ')' as it is matched
                } else {
                    insertions++; // Need to insert a ')'
                }
            } else {
                insertions++; // Need to insert a '('
                if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                    i++; // Skip the next ')' as it is matched
                } else {
                    insertions++; // Need to insert a ')'
                }
            }
        }
    }
    insertions += open * 2; // Each remaining '(' needs two ')'
    return insertions;
}

public int minInsertions(String s) {
    int left = 0, right = 0, insertions = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right < 2) {
                insertions += 2 - right;
                right = 0;
            }
            left++;
        } else {
            right++;
            if (right == 2) {
                right = 0;
                if (left > 0) {
                    left--;
                } else {
                    insertions++;
                }
            }
        }
    }
    if (right == 1) {
        insertions++;
        if (left > 0) {
            left--;
            insertions++;
        }
    } else if (right == 2 && left > 0) {
        left--;
    }
    return insertions + left * 2;
}

