public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;

    // Generate all Fibonacci numbers less than or equal to k
    int a = 1, b = 1;
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
    }

    // Now b is the smallest Fibonacci number greater than k, so we use a
    int count = 0;
    while (k > 0) {
        if (a <= k) {
            k -= a;
            count++;
        }
        int temp = a;
        a = b - a;
        b = temp;
    }

    return count;
}

