    for (int i = 0; i < n; i++) {
        if (remainingValue > 25) {
            result.append('a');
            remainingValue -= 25;
        } else {
            char c = (char)('a' + remainingValue);
            result.append(c);
            remainingValue = 0;
        }
    }

    return result.toString();
}

