    for (int i = 0; i < n; i++) {
        if (remaining >= 25) {
            // We can put 'z' here
            sb.append('z');
            remaining -= 25;  // 'z' contributes 26, but we already counted 1 for 'a'
        } else {
            // We need to put a letter that makes the sum exactly k
            sb.append((char)('a' + remaining));
            remaining = 0;
        }
    }

    return sb.toString();
}

