public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    // Add all single digit numbers to the queue and result if within range
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
        if (i >= low && i <= high) {
            result.add(i);
        }
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) continue;
        int lastDigit = num % 10;

        int nextLower = num * 10 + (lastDigit - 1);
        int nextHigher = num * 10 + (lastDigit + 1);

        if (lastDigit > 0 && nextLower <= high) {
            queue.offer(nextLower);
            if (nextLower >= low) {
                result.add(nextLower);
            }
        }

        if (lastDigit < 9 && nextHigher <= high) {
            queue.offer(nextHigher);
            if (nextHigher >= low) {
                result.add(nextHigher);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        findSteppingNumbersHelper(i, low, high, result);
    }
    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersHelper(int num, int low, int high, List<Integer> result) {
    if (num > high) {
        return;
    }
    if (num >= low) {
        result.add(num);
    }
    int lastDigit = num % 10;
    if (lastDigit > 0) {
        findSteppingNumbersHelper(num * 10 + lastDigit - 1, low, high, result);
    }
    if (lastDigit < 9) {
        findSteppingNumbersHelper(num * 10 + lastDigit + 1, low, high, result);
    }
}

