private static int backtrack(int[] A, boolean[] used, List<Integer> path) {
    if (path.size() == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            if (path.isEmpty() || isPerfectSquare(path.get(path.size() - 1) + A[i])) {
                used[i] = true;
                path.add(A[i]);
                count += backtrack(A, used, path);
                path.remove(path.size() - 1);
                used[i] = false;

                // Skip duplicates
                while (i < A.length - 1 && A[i] == A[i + 1]) {
                    i++;
                }
            }
        }
    }
    return count;
}

