public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;

    // Find the first decreasing digit from the right
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) that is larger than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after (i) to get the smallest possible number
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the char array back to an integer
    long result = Long.parseLong(new String(digits));

    // Check if the result is within the integer range
    if (result > Integer.MAX_VALUE) {
        return -1;
    }

    return (int) result;
}

