    int len = digits.length;

    // Find the rightmost digit that is smaller than the digit next to it
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) which is greater than digits[i]
    int smallest = i + 1;
    for (int j = i + 1; j < len; j++) {
        if (digits[j] > digits[i] && digits[j] < digits[smallest]) {
            smallest = j;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[smallest];
    digits[smallest] = temp;

    // Sort the digits after the position i
    Arrays.sort(digits, i + 1, len);

    // Convert the character array back to an integer
    long result = Long.parseLong(new String(digits));

    // Check if the result is within the integer range
    if (result > Integer.MAX_VALUE) {
        return -1;
    }

    return (int) result;
}

